<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Zaid Workspace</title>
    <meta name="description" content="Zaid workspace for planning tasks and schedules.">
    <style>
        :root { --ink:#2b193b; --muted:#756980; --line:#e8e1ee; --paper:#fff; --canvas:#f8f6fb; --lavender:#7151a8; --lavender-soft:#f0eafe; --lavender-pale:#faf7ff; --success:#2d8d68; --danger:#c54f62; }
        * { box-sizing:border-box } [hidden] { display:none!important } html { background:var(--canvas) } body { margin:0; background:var(--canvas); color:var(--ink); font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; -webkit-font-smoothing:antialiased } button,input,textarea { font:inherit } button { cursor:pointer } button:focus-visible,input:focus-visible,textarea:focus-visible { outline:3px solid #c9b6f2; outline-offset:2px }
        .skip { position:absolute;left:16px;top:-50px;background:var(--ink);color:#fff;padding:10px 14px;border-radius:8px;z-index:5 }.skip:focus { top:16px }.shell { height:100dvh;width:100%;overflow:hidden;background:var(--paper);box-shadow:0 0 0 1px var(--line) }
        .topbar { height:70px;display:flex;align-items:center;gap:24px;padding:0 28px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.94);position:sticky;top:0;z-index:2 }.logo { display:flex;align-items:center;gap:9px;color:var(--lavender);font-size:21px;font-weight:800;letter-spacing:-.055em;white-space:nowrap }.logo img { width:29px;height:29px;object-fit:contain }.main-nav { display:flex;gap:4px;height:100%;align-items:center }.main-nav a { display:grid;place-items:center;align-self:stretch;border-bottom:2px solid transparent;color:var(--muted);padding:0 14px;font-weight:650;text-decoration:none;transition:color .18s ease,border-color .18s ease }.main-nav a:hover { color:var(--ink) }.main-nav a.active { color:var(--lavender);border-color:var(--lavender) }.account { margin-left:auto;display:flex;align-items:center;gap:12px;color:var(--muted);font-size:12px }.avatar { display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:var(--lavender-soft);color:var(--lavender);font-weight:800 }.logout { border:1px solid var(--line);border-radius:9px;background:#fff;padding:8px 11px;color:var(--ink);font-weight:650;transition:background .18s ease,transform .12s ease }.logout:hover { background:var(--lavender-pale) }.logout:active,.primary:active,.icon-button:active { transform:scale(.96) }
        main { height:calc(100dvh - 70px);overflow:hidden;padding:28px }.view { height:100% }.view[hidden] { display:none }.workspace { height:100%;display:grid;grid-template-columns:220px minmax(0,1fr);gap:28px }.workspace>section { display:flex;min-height:0;flex-direction:column }.workspace>section .content-head { flex:0 0 auto }.workspace>section .calendar-layout { flex:1;min-height:0 }.rail { border-right:1px solid var(--line);padding-right:24px }.rail-label { color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;margin-bottom:12px }.mini-calendar { display:grid;grid-template-columns:repeat(7,1fr);gap:3px;font-variant-numeric:tabular-nums;margin-bottom:26px }.mini-calendar span,.mini-calendar button { display:grid;place-items:center;height:28px;border:0;border-radius:8px;background:transparent;color:var(--ink);font-size:11px }.mini-calendar .mini-head { color:var(--muted);font-size:9px;font-weight:800 }.mini-calendar .mini-day { position:relative;transition:background-color .15s ease,color .15s ease,transform .12s ease }.mini-calendar .mini-day:hover { background:var(--lavender-soft);color:var(--lavender) }.mini-calendar .mini-day:active { transform:scale(.96) }.mini-calendar .mini-outside { color:#c5bdca }.mini-calendar .mini-selected { background:var(--lavender);color:#fff;font-weight:800 }.mini-calendar .mini-selected:hover { background:#60438f;color:#fff }.rail-list { display:grid;gap:4px }.rail-list button { border:0;border-radius:8px;background:transparent;text-align:left;padding:9px 10px;color:var(--ink);font-weight:600 }.rail-list button:hover { background:var(--lavender-pale) }.rail-note { margin-top:30px;padding-top:20px;border-top:1px solid var(--line);color:var(--muted);font-size:12px;line-height:1.6 }
        .content-head { display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:24px }.eyebrow { color:var(--lavender);font-size:12px;font-weight:800;letter-spacing:.07em;text-transform:uppercase }.title { margin:3px 0 0;font-size:30px;line-height:1.1;letter-spacing:-.055em;text-wrap:balance }.subcopy { margin:7px 0 0;color:var(--muted) }.calendar-actions { display:flex;align-items:center;gap:8px }.view-filter { display:flex;align-items:center;gap:6px;min-height:40px;border:1px solid var(--line);border-radius:9px;padding:0 9px;color:var(--muted);font-size:12px;font-weight:700 }.view-filter select { border:0;background:#fff;color:var(--ink);font:inherit;font-weight:700;outline:0 }.icon-button,.secondary,.primary { min-height:40px;border-radius:9px;padding:0 13px;font-weight:700;transition:background .18s ease,transform .12s ease }.icon-button,.secondary { border:1px solid var(--line);background:#fff;color:var(--ink) }.icon-button:hover,.secondary:hover { background:var(--lavender-pale) }.arrow-button { display:grid;place-items:center;width:40px;padding:0 }.arrow-button svg { width:18px;height:18px;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round;stroke-width:2.1 }.primary { border:1px solid var(--lavender);background:var(--lavender);color:#fff;box-shadow:0 5px 13px rgba(113,81,168,.18) }.primary:hover { background:#60438f }.calendar-layout { display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:22px }.calendar-panel,.task-group,.ai-card { background:#fff;border:1px solid var(--line);border-radius:16px }.calendar-panel { display:flex;min-height:0;overflow:hidden;flex-direction:column;box-shadow:0 10px 30px rgba(62,38,88,.045) }.calendar-grid { flex:1;min-height:0;grid-template-rows:repeat(6,minmax(0,1fr));transform-origin:center;will-change:transform,opacity }.calendar-grid[hidden],.week-grid[hidden] { display:none }.weekdays,.calendar-grid { display:grid;grid-template-columns:repeat(7,minmax(0,1fr)) }.weekdays { border-bottom:1px solid var(--line);background:#fcfbfd }.weekdays div { padding:11px 8px;text-align:right;color:var(--muted);font-size:11px;font-weight:800;text-transform:uppercase }.day { min-height:0;border:0;border-right:1px solid var(--line);border-bottom:1px solid var(--line);background:#fff;padding:9px;text-align:left;vertical-align:top;color:var(--ink);transition:background .18s ease,box-shadow .18s ease }.week-grid { display:grid;grid-template-columns:50px repeat(7,minmax(0,1fr));grid-template-rows:repeat(13,48px);max-height:calc(100dvh - 260px);min-height:580px;overflow:auto;background:#fff }.week-time { border-right:1px solid var(--line);border-bottom:1px solid var(--line) }.week-cell { border:0;border-right:1px solid var(--line);border-bottom:1px solid var(--line) }.week-time { padding:6px 8px 0 0;color:var(--muted);font-size:10px;text-align:right }.week-cell { position:relative;background:#fff }.week-event { position:absolute;inset:5px 5px auto;border:0;border-left:3px solid var(--lavender);border-radius:5px;background:var(--lavender-soft);padding:5px 7px;color:#50377d;font-size:11px;font-weight:700;text-align:left;overflow:hidden;white-space:nowrap;text-overflow:ellipsis }.week-day { display:grid;place-items:center;border-right:1px solid var(--line);border-bottom:1px solid var(--line);color:var(--muted);font-size:11px;font-weight:800;text-transform:uppercase }.week-day strong { display:block;color:var(--ink);font-size:18px;line-height:1.2 }.week-day.today strong { display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--lavender);color:#fff }.day:nth-child(7n) { border-right:0 }.day:hover { background:var(--lavender-pale) }.day.outside { color:#c5bdca;background:#fdfcff }.day.selected { background:#faf7ff;box-shadow:inset 0 0 0 2px var(--lavender) }.day.today .day-number { background:var(--lavender);color:#fff }.day-number { display:grid;place-items:center;width:27px;height:27px;border-radius:50%;font-variant-numeric:tabular-nums;font-weight:700 }.event-pill { display:block;width:100%;margin-top:7px;overflow:hidden;border:0;border-left:3px solid var(--lavender);border-radius:4px;background:var(--lavender-soft);padding:4px 6px;color:#50377d;font-size:11px;font-weight:700;text-align:left;white-space:nowrap;text-overflow:ellipsis;cursor:pointer;transition:background .15s ease,transform .15s ease }.event-pill.task-pill { border-left-color:#38a169;background:#e8f7ef;color:#236644 }.event-pill:hover { background:#dfd2f7;transform:translateX(2px) }.event-pill.task-pill:hover { background:#d5f1e2 }.more { margin-top:4px;color:var(--lavender);font-size:11px;font-weight:700 }
        .panel-head { display:flex;align-items:flex-start;justify-content:space-between;gap:10px;padding-bottom:14px;border-bottom:1px solid var(--line) }.panel-head strong { font-size:16px;letter-spacing:-.025em }.date-copy { margin-top:2px;color:var(--muted);font-size:12px }.agenda-items { display:grid;gap:8px;max-height:390px;overflow:auto;padding-top:14px }.agenda-item { display:flex;gap:10px;align-items:flex-start;border:1px solid var(--line);border-radius:10px;padding:10px;transition:background .18s ease,box-shadow .18s ease }.agenda-item:hover { background:var(--lavender-pale);box-shadow:0 4px 12px rgba(62,38,88,.06) }.check { appearance:none;flex:0 0 17px;width:17px;height:17px;margin:2px 0 0;border:1.5px solid #b7a9c2;border-radius:5px;background:#fff;cursor:pointer }.check:checked { border-color:var(--lavender);background:var(--lavender) }.check:checked::after { content:'✓';display:block;color:#fff;font-size:12px;line-height:15px;text-align:center }.agenda-main { min-width:0;flex:1;border:0;background:transparent;text-align:left;padding:0;color:inherit }.agenda-title { overflow:hidden;font-weight:700;white-space:nowrap;text-overflow:ellipsis }.agenda-meta { color:var(--muted);font-size:11px;margin-top:2px }.empty { color:var(--muted);padding:22px 0;text-align:center }.ai-card { display:flex;flex-direction:column;height:100%;min-height:0;padding:18px;background:linear-gradient(145deg,#fff 0%,#faf7ff 100%);box-shadow:0 10px 30px rgba(62,38,88,.045) }.ai-head { display:flex;align-items:flex-start;justify-content:space-between;gap:12px }.ai-card h2 { margin:0;font-size:18px;letter-spacing:-.035em }.ai-card p { margin:6px 0 14px;color:var(--muted);font-size:13px }.clear-chat { display:grid;place-items:center;flex:0 0 40px;width:40px;height:40px;border:0;border-radius:10px;background:transparent;padding:0;color:var(--muted) }.clear-chat svg { width:17px;height:17px;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round;stroke-width:1.8 }.clear-chat:hover { background:var(--lavender-soft);color:var(--lavender) }.prompt-suggestions { display:flex;gap:6px;overflow-x:auto;margin:0 -2px 12px;padding:2px;scrollbar-width:none }.prompt-suggestions::-webkit-scrollbar { display:none }.prompt-suggestions button { flex:none;min-height:34px;border:1px solid #dfd4ee;border-radius:9px;background:#fff;padding:0 10px;color:#5e4778;font-size:11px;font-weight:700;transition:background-color .15s ease,border-color .15s ease,transform .12s ease }.prompt-suggestions button:hover { border-color:#c9b6e1;background:var(--lavender-pale) }.prompt-suggestions button:active { transform:scale(.96) }.chat-history { display:grid;align-content:start;gap:10px;flex:1;min-height:0;overflow-y:auto;padding:5px 2px 14px }.chat-message { max-width:88%;border-radius:14px;padding:10px 12px;font-size:12px;line-height:1.5;white-space:pre-wrap;animation:message-in .18s ease-out }.chat-message.user { justify-self:end;border-radius:14px 14px 4px 14px;background:var(--lavender);color:#fff }.chat-message.assistant { justify-self:start;border-radius:14px 14px 14px 4px;background:var(--lavender-soft);color:#4e3876 }.chat-empty { align-self:start;margin:12px 0;color:var(--muted);font-size:12px;text-align:left }.chat-empty strong { display:block;margin-bottom:4px;color:var(--ink);font-size:13px }.chat-composer { display:grid;grid-template-columns:minmax(0,1fr) 44px;gap:8px;align-items:end;border-top:1px solid var(--line);padding-top:12px }.chat-composer textarea { width:100%;min-height:44px;max-height:110px;border:1px solid #cbb9ec;border-radius:12px;background:#fff;padding:11px 12px;color:var(--ink);resize:none;box-shadow:inset 0 1px 2px rgba(43,25,59,.04) }.chat-composer textarea::placeholder { color:#8b7c9c;opacity:1 }.chat-composer textarea:focus { border-color:var(--lavender);box-shadow:0 0 0 3px #e5d9fa;outline:0 }.chat-composer .primary { display:grid;place-items:center;width:44px;min-width:44px;padding:0 }.send-icon { width:19px;height:19px;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round;stroke-width:1.9;transform:translateX(1px) }.ai-actions { display:none } @keyframes message-in { from { opacity:0;transform:translateY(4px) } to { opacity:1;transform:translateY(0) } }.status { color:var(--muted);font-size:11px }.status.error { color:var(--danger) }.status.success { color:var(--success) }.assistant-response { margin-top:12px;border-left:3px solid var(--lavender);border-radius:0 9px 9px 0;background:var(--lavender-soft);padding:10px 12px;color:#4e3876;font-size:12px;white-space:pre-wrap }.confirmation { margin-top:10px;border-left:3px solid var(--lavender);background:var(--lavender-soft);padding:9px;color:#4e3876;font-size:12px }.confirmation button { margin:8px 5px 0 0;border:0;border-radius:7px;padding:6px 8px;background:var(--lavender);color:#fff;font-weight:700 }.confirmation button:last-child { background:transparent;color:#4e3876;text-decoration:underline }.agenda-modal { width:min(520px,100%);max-height:min(80dvh,650px);overflow:auto }
        .tasks-head { display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:24px }.task-tools { display:flex;gap:8px }.task-board { display:flex;gap:14px;align-items:flex-start;min-height:calc(100dvh - 220px);overflow-x:auto;padding:2px 2px 18px }.task-group { flex:0 0 286px;min-height:360px;padding:0;border-radius:12px;background:#f7f5fa;box-shadow:none }.task-group-head { display:flex;align-items:center;justify-content:space-between;padding:15px 14px 9px;border:0 }.task-group-head h2 { margin:0;font-size:14px;letter-spacing:-.015em }.task-count { display:grid;place-items:center;min-width:22px;height:22px;border-radius:7px;background:#eae5f1;color:#665779;font-variant-numeric:tabular-nums;font-size:11px;font-weight:800 }.add-task-link { display:block;width:calc(100% - 18px);margin:5px 9px 9px;border:0;border-radius:8px;background:transparent;padding:9px;text-align:left;color:#716184;font-size:12px;font-weight:700 }.add-task-link:hover { background:#ece7f3;color:var(--lavender) }.task-list { display:grid;gap:7px;padding:0 9px 9px }.task-card { display:flex;gap:9px;align-items:flex-start;border:1px solid #ebe6ef;border-radius:9px;background:#fff;padding:11px;box-shadow:0 1px 2px rgba(45,27,61,.04);transition:box-shadow .15s ease,transform .15s ease }.task-card:hover { box-shadow:0 5px 13px rgba(45,27,61,.09);transform:translateY(-1px) }.task-card .agenda-main { padding-top:0 }.task-card.completed .agenda-title { color:var(--muted);text-decoration:line-through }.task-card .check:checked { background:var(--success);border-color:var(--success) }
        .modal { position:fixed;inset:0;z-index:4;display:grid;place-items:center;padding:18px;background:rgba(34,22,45,.32);backdrop-filter:blur(8px) }.modal[hidden] { display:none }.modal-card { width:min(500px,100%);border-radius:22px;background:#fff;padding:24px;box-shadow:0 26px 80px rgba(47,28,65,.22),0 0 0 1px rgba(74,51,92,.08) }.date-prompt { position:relative;width:min(460px,100%);border-radius:22px;background:#fff;padding:25px;box-shadow:0 26px 80px rgba(47,28,65,.22),0 0 0 1px rgba(74,51,92,.08) }.date-prompt h2 { margin:0;font-size:21px;letter-spacing:-.04em }.date-prompt p { margin:6px 0 18px;color:var(--muted);font-size:13px }.date-chip { display:inline-flex;align-items:center;min-height:30px;border-radius:999px;background:var(--lavender-soft);padding:0 11px;color:var(--lavender);font-size:12px;font-weight:800 }.date-prompt textarea { width:100%;min-height:105px;margin-top:15px;border:1px solid #cbb9ec;border-radius:13px;background:#fcfbfd;padding:12px;color:var(--ink);resize:vertical }.date-prompt textarea:focus { border-color:var(--lavender);box-shadow:0 0 0 3px #e5d9fa;outline:0 }.date-prompt-actions { display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:17px }.date-prompt-actions>span { color:var(--muted);font-size:11px }.manual-button { border:0;border-radius:9px;background:var(--lavender-soft);padding:9px 11px;color:var(--lavender);font-size:12px;font-weight:800 }.manual-button:hover { background:#e5d9fa }.modal-card h2 { margin:0;font-size:20px;letter-spacing:-.04em }.field { display:grid;gap:5px;margin:13px 0;color:var(--muted);font-size:12px;font-weight:650 }.field input,.field textarea { width:100%;border:1px solid var(--line);border-radius:9px;background:#fff;padding:10px;color:var(--ink);resize:vertical }.two { display:grid;grid-template-columns:1fr 1fr;gap:11px }.modal-actions { display:flex;justify-content:flex-end;gap:8px;margin-top:17px }.danger { margin-right:auto;border:0;background:transparent;color:var(--danger);font-weight:700 }.danger:hover { text-decoration:underline }.composer { position:relative;width:min(520px,100%);border-radius:24px;background:#fff;padding:26px;box-shadow:0 26px 80px rgba(47,28,65,.22),0 0 0 1px rgba(74,51,92,.08) }.composer h2 { display:block;margin:0 44px 18px 0;font-size:13px;color:var(--muted);letter-spacing:.08em;text-transform:uppercase }.modal-close { position:absolute;top:18px;right:18px;display:grid;place-items:center;width:40px;height:40px;border:0;border-radius:10px;background:transparent;color:var(--muted) }.modal-close:hover { background:var(--lavender-soft);color:var(--lavender) }.modal-close svg { width:18px;height:18px;fill:none;stroke:currentColor;stroke-linecap:round;stroke-width:2 }.confirm-dialog { position:fixed;inset:0;z-index:6;display:grid;place-items:center;padding:18px;background:rgba(34,22,45,.32);backdrop-filter:blur(8px) }.confirm-dialog[hidden] { display:none }.confirm-card { width:min(390px,100%);border-radius:18px;background:#fff;padding:22px;box-shadow:0 26px 80px rgba(47,28,65,.22),0 0 0 1px rgba(74,51,92,.08) }.confirm-card h2 { margin:0;font-size:17px;letter-spacing:-.025em }.confirm-card p { margin:7px 0 0;color:var(--muted);font-size:13px;line-height:1.5 }.confirm-actions { display:flex;justify-content:flex-end;gap:8px;margin-top:20px }.composer-title { width:100%;border:0!important;border-bottom:1.5px solid #cfc3dc!important;border-radius:0!important;background:transparent!important;padding:4px 0 12px!important;font-size:26px;font-weight:650;letter-spacing:-.035em;color:var(--ink);outline:0 }.composer-title:focus { border-color:var(--lavender)!important;box-shadow:none!important }.composer .field { margin:18px 0 }.composer .field input:not([type=checkbox]),.composer select { min-height:44px;border:1px solid var(--line);border-radius:10px;background:#faf9fc;padding:10px 12px;color:var(--ink) }.composer .all-day-field { margin:4px 0 18px }.all-day-row { display:flex;min-height:44px;align-items:center;justify-content:space-between;gap:16px;color:var(--ink);font-size:13px }.all-day-row small { display:block;margin-top:2px;color:var(--muted);font-size:11px;font-weight:500 }.quick-all-day-switch { position:relative;flex:0 0 42px;width:42px;height:24px;margin:0;appearance:none;border:0!important;border-radius:999px!important;background:#ddd5e7!important;padding:0!important;cursor:pointer;transition:background-color .18s ease }.quick-all-day-switch::after { content:'';position:absolute;top:3px;left:3px;width:18px;height:18px;border-radius:50%;background:#fff;box-shadow:0 1px 4px rgba(43,25,59,.22);transition:transform .18s ease }.quick-all-day-switch:checked { background:var(--lavender)!important }.quick-all-day-switch:checked::after { transform:translateX(18px) }.composer .tab-row { display:grid;grid-template-columns:1fr 1fr;gap:4px;width:190px;margin:16px 0 20px;border-radius:11px;background:#f1edf5;padding:4px }.composer .tab-row button { min-height:36px;border:0;border-radius:8px;background:transparent;padding:0 14px;color:var(--muted);font-weight:700 }.composer .tab-row button.primary { background:#fff;color:var(--lavender);box-shadow:0 2px 8px rgba(48,29,67,.09) }.composer .details { min-height:76px!important;border:1px solid var(--line)!important;border-radius:10px!important;background:#faf9fc!important;padding:11px 12px!important;font-size:14px }.reminder-fields { display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:18px }.reminder-fields .field { margin:0 }.reminder-fields select,.reminder-fields input { width:100% }.reminder-label { display:flex;align-items:center;gap:6px }.reminder-label svg { width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round }.reminder-hint { margin:7px 0 0;color:var(--muted);font-size:11px;line-height:1.4 }.composer .modal-actions { align-items:center;margin-top:24px;padding-top:18px;border-top:1px solid var(--line) }.composer .primary { border-radius:10px;background:var(--lavender) }.composer .secondary { border:0;background:transparent;color:var(--muted) }.composer .danger { color:var(--danger) }
        @media(max-width:1050px){.workspace{grid-template-columns:1fr}.rail{display:none}.calendar-layout{grid-template-columns:minmax(0,1fr) 275px}.week-grid{max-height:600px}} @media(max-width:760px){.shell{height:auto;overflow:visible}main{height:auto;overflow:visible}.view,.workspace{height:auto}.topbar{height:auto;min-height:64px;padding:0 16px;gap:8px;flex-wrap:wrap}.main-nav{order:3;width:100%;height:44px}.main-nav a{flex:1}.account{margin-left:auto}.account .email{display:none}main{padding:16px}.calendar-layout{grid-template-columns:1fr}.day{min-height:76px;padding:6px}.weekdays div{font-size:9px;padding:8px 3px}.event-pill{margin-top:5px}.agenda-panel{min-height:auto}.task-board{grid-template-columns:minmax(260px,1fr) minmax(260px,1fr) minmax(260px,1fr)}.title{font-size:25px}.content-head,.tasks-head{align-items:flex-start;flex-direction:column}.calendar-actions,.task-tools{width:100%}.calendar-actions .primary,.task-tools .primary{margin-left:auto}.account{font-size:0}.logout{font-size:12px}.two{grid-template-columns:1fr}}
        @media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition:none!important}}
    </style>
</head>
<body>
<a class="skip" href="#main">Skip to workspace</a>
<div class="shell">
    <header class="topbar">
        <div class="logo"><img src="/images/brand/zaid-logo.png" alt="">Zaid Workspace</div>
        <nav class="main-nav" aria-label="Primary navigation"><a class="{{ $initialView === 'calendar' ? 'active' : '' }}" href="/dashboard">Calendar</a><a class="{{ $initialView === 'tasks' ? 'active' : '' }}" href="/dashboard/tasks">Tasks</a></nav>
        <div class="account"><span class="email" id="profile-email">Loading…</span><span class="avatar" id="profile-initial">Z</span><button class="logout" type="button" id="logout">Logout</button></div>
    </header>
    <main id="main">
        <section class="view" id="calendar-view" aria-label="Calendar view" @if ($initialView !== 'calendar') hidden @endif>
            <div class="workspace">
                <aside class="rail" aria-label="Calendar sidebar"><div class="rail-label">This month</div><div class="mini-calendar" id="mini-calendar"></div><div class="rail-list"><button type="button" id="today-nav">Today</button><button type="button" id="tasks-nav">View all tasks</button></div><p class="rail-note">Your tasks and schedule live in Zaid. Google is used only for sign-in.</p></aside>
                <section>
                    <div class="content-head"><div><div class="eyebrow">Planning</div><h1 class="title" id="month-title">Calendar</h1><p class="subcopy">Klik tanggal untuk buat jadwal. Scroll kalender untuk pindah bulan.</p></div><div class="calendar-actions"><button class="icon-button arrow-button" type="button" id="previous-month" aria-label="Previous period"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14.5 5-7 7 7 7"/></svg></button><button class="secondary" type="button" id="today">Today</button><button class="icon-button arrow-button" type="button" id="next-month" aria-label="Next period"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9.5 5 7 7-7 7"/></svg></button><label class="view-filter"><select id="calendar-mode" aria-label="Calendar view"><option value="month">Month</option><option value="week">Week</option></select></label><button class="primary" type="button" id="new-task">+ Buat jadwal</button></div></div>
                    <div class="calendar-layout"><section class="calendar-panel" id="calendar-panel" aria-label="Calendar" title="Scroll up or down to change period"><div class="weekdays" id="weekdays"><div>Sun</div><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div></div><div class="calendar-grid" id="calendar-grid" role="grid"></div><div class="week-grid" id="week-grid" hidden></div></section><aside class="ai-card" aria-label="Ask Zaid"><div class="ai-head"><div><h2>Ask Zaid</h2><p>Atur jadwal pakai bahasa sehari-hari.</p></div><button class="clear-chat" type="button" id="clear-chat" aria-label="Hapus riwayat chat" title="Hapus riwayat chat"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3m-9 0 1 13h10l1-13M10 11v5m4-5v5"/></svg></button></div><div class="prompt-suggestions" aria-label="Contoh perintah"><button type="button" data-prompt="cek jadwal hari ini">Jadwal hari ini</button><button type="button" data-prompt="buat meeting besok jam 9">Buat jadwal</button><button type="button" data-prompt="pindah meeting besok ke jam 10">Pindah jadwal</button></div><div class="chat-history" id="chat-history" aria-live="polite"></div><div id="confirmation" class="confirmation" hidden></div><div class="chat-composer"><textarea id="prompt" aria-label="Message Zaid" placeholder="Contoh: pindah meeting besok ke jam 10"></textarea><button class="primary" type="button" id="ask" aria-label="Kirim pesan"><svg class="send-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg></button></div><span class="status" id="status" role="status" aria-live="polite"></span></aside></div>
                </section>
            </div>
        </section>
        <section class="view" id="tasks-view" aria-label="Tasks view" @if ($initialView !== 'tasks') hidden @endif>
            <div class="tasks-head"><div><div class="eyebrow">Workspace</div><h1 class="title">My tasks</h1><p class="subcopy">Pilih list, tambah pekerjaan, lalu centang saat selesai.</p></div><div class="task-tools"><label class="view-filter">Show <select id="task-filter"><option value="all">All tasks</option><option value="today">Today</option><option value="upcoming">Upcoming</option></select></label><button class="secondary" type="button" id="new-list">+ New list</button><button class="primary" type="button" id="tasks-add">+ Add task</button></div></div>
            <div class="task-board" id="task-board"></div>
        </section>
    </main>
</div>
<div class="modal" id="date-action-modal" hidden><form class="date-prompt" id="date-prompt-modal"><button class="modal-close" type="button" id="close-date-prompt" aria-label="Tutup"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button><h2>Rencanakan tanggal ini</h2><p>Tulis seperti biasa. Zaid pakai tanggal yang kamu pilih.</p><span class="date-chip" id="date-prompt-date"></span><textarea id="date-prompt-input" required maxlength="1000" placeholder="Contoh: meeting tim jam 10 pagi"></textarea><div class="date-prompt-actions"><button class="manual-button" type="button" id="quick-manual">Manual</button><span>Periksa lalu kirim</span><button class="primary" type="submit">Kirim</button></div></form></div>
<div class="modal" id="event-modal" hidden><form class="composer" id="event-form"><h2 id="event-form-title">Jadwal manual</h2><button class="modal-close" type="button" id="close-event" aria-label="Tutup"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button><input id="event-id" type="hidden"><label class="field">Judul jadwal<input id="event-title" required maxlength="255" placeholder="Contoh: Meeting tim"></label><div class="two"><label class="field">Mulai<input id="event-start" type="datetime-local" required></label><label class="field">Selesai<input id="event-end" type="datetime-local"></label></div><label class="field all-day-field"><span class="all-day-row"><span>Seharian<small>Jadwal tanpa jam khusus.</small></span><input class="quick-all-day-switch" id="event-all-day" type="checkbox" aria-label="Jadwal seharian"></span></label><label class="field">Catatan<textarea class="details" id="event-description" rows="2" placeholder="Tambahkan catatan (opsional)"></textarea></label><div class="reminder-fields"><label class="field"><span class="reminder-label"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>Reminder</span><select id="event-reminder"><option value="">Tanpa reminder</option><option value="15">15 menit sebelumnya</option><option value="30">30 menit sebelumnya</option><option value="60">1 jam sebelumnya</option><option value="1440">1 hari sebelumnya</option><option value="custom">Custom</option></select><input id="event-reminder-custom" type="number" min="1" placeholder="Menit" hidden></label><label class="field" id="event-reminder-channel-field" hidden>Channel<select id="event-reminder-channel"><option value="whatsapp">WhatsApp</option><option value="app">App</option><option value="both">WhatsApp + App</option></select></label></div><p class="reminder-hint" id="event-reminder-hint" hidden>Default reminder dikirim lewat WhatsApp.</p><div class="modal-actions"><button class="danger" type="button" id="delete-event" hidden>Delete event</button><button class="secondary" type="button" id="cancel-event">Batal</button><button class="primary" type="submit">Simpan event</button></div></form></div>
<div class="modal" id="task-modal" hidden><form class="composer" id="task-form"><h2 id="form-title">New task</h2><input id="task-id" type="hidden"><input class="composer-title" id="task-title" required maxlength="255" placeholder="Add title"><div class="tab-row"><button type="button">Event</button><button class="primary" type="button">Task</button></div><div class="two"><label class="field">Batas tanggal<input id="task-date" type="date"></label><label class="field">Jam<input id="task-time-visible" type="time"></label></div><label class="field">List<select id="task-list-id"></select></label><label class="field">Catatan<textarea class="details" id="task-description" rows="2" placeholder="Tambahkan catatan (opsional)"></textarea></label><div class="reminder-fields"><label class="field"><span class="reminder-label"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>Reminder</span><select id="task-reminder"><option value="">Tanpa reminder</option><option value="15">15 menit sebelumnya</option><option value="30">30 menit sebelumnya</option><option value="60">1 jam sebelumnya</option><option value="1440">1 hari sebelumnya</option><option value="custom">Custom</option></select><input id="task-reminder-custom" type="number" min="1" placeholder="Menit" hidden></label><label class="field" id="task-reminder-channel-field" hidden>Channel<select id="task-reminder-channel"><option value="whatsapp">WhatsApp</option><option value="app">App</option><option value="both">WhatsApp + App</option></select></label></div><p class="reminder-hint" id="task-reminder-hint" hidden>Default reminder dikirim lewat WhatsApp.</p><input id="task-time" type="hidden"><input id="task-all-day" type="hidden"><div class="modal-actions"><button class="danger" type="button" id="delete-task" hidden>Delete</button><button class="secondary" type="button" id="cancel-task">Batal</button><button class="primary" type="submit">Simpan</button></div></form></div>
<div class="confirm-dialog" id="confirm-dialog" hidden><section class="confirm-card" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><h2 id="confirm-title">Hapus riwayat chat?</h2><p id="confirm-copy">Riwayat Ask Zaid akan dihapus permanen.</p><div class="confirm-actions"><button class="secondary" type="button" id="confirm-cancel">Batal</button><button class="primary" type="button" id="confirm-ok">Hapus riwayat</button></div></section></div>
<div class="modal" id="list-modal" hidden><form class="modal-card" id="list-form"><h2>New list</h2><p class="subcopy">Buat tempat untuk mengelompokkan pekerjaan.</p><label class="field">Nama list<input id="list-name" required maxlength="100" autocomplete="off" placeholder="Contoh: Kuliah"></label><div class="modal-actions"><button class="secondary" type="button" id="cancel-list">Batal</button><button class="primary" type="submit">Buat list</button></div></form></div>
<script>
const initialView = @json($initialView);
const tokenKey='zaid_web_access_token',verificationKey='zaid_verification_id',phoneKey='zaid_phone_number';
const state={visibleMonth:new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedDate:new Date().toISOString().slice(0,10),monthDays:new Map(),events:[],calendarTasks:[],allTasks:[],taskLists:[],pendingPrompt:null,view:initialView,calendarMode:'month',taskFilter:'all',quickType:'event'};
const $=id=>document.getElementById(id);
const pad=n=>String(n).padStart(2,'0');
function dateKey(date){return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}`} function monthKey(date){return dateKey(date).slice(0,7)}
function clearSession(){[tokenKey,verificationKey,phoneKey].forEach(key=>localStorage.removeItem(key))}
function setText(id,text){$(id).textContent=text||''} function status(message,type=''){const node=$('status');node.textContent=message||'';node.className=`status ${type}`} function chatMessage(text,role){const item=document.createElement('div');item.className=`chat-message ${role}`;item.textContent=text;$('chat-history').append(item);$('chat-history').scrollTop=$('chat-history').scrollHeight;return item} function renderChatEmpty(message='Tanya jadwal yang mau dibuat atau diubah.'){const empty=document.createElement('p');empty.className='chat-empty';empty.innerHTML=`<strong>Apa yang bisa Zaid bantu?</strong>${message}<br>Contoh: “buat meeting besok jam 9”`;return empty} async function loadChat(){const data=await api('/prompts');const box=$('chat-history');box.replaceChildren();const items=data.data.items||[];if(!items.length){box.append(renderChatEmpty());return}items.forEach(item=>{chatMessage(item.text,'user');if(item.response)chatMessage(item.response,'assistant')})}
async function api(path,options={}){const response=await fetch('/api/v1'+path,{...options,headers:{Accept:'application/json',Authorization:`Bearer ${localStorage.getItem(tokenKey)}`,...(options.headers||{})}});const data=await response.json().catch(()=>({message:'Unexpected server response'}));if(!response.ok)throw data;return data}
function showView(name){window.location.assign(name==='tasks'?'/dashboard/tasks':'/dashboard')}
async function boot(){if(!localStorage.getItem(tokenKey)){location.replace('/app');return}try{const [onboarding,me]=await Promise.all([api('/onboarding/status'),api('/me')]);if(onboarding.data.next_step!=='dashboard'){location.replace('/app');return}setText('profile-email',me.data.email);setText('profile-initial',(me.data.full_name||me.data.email||'Z').slice(0,1).toUpperCase())}catch(error){clearSession();location.replace('/app');return}await Promise.all([loadMonth(),loadTasks(),loadTaskLists(),loadChat()].map(request=>request.catch(error=>status(error.message||'Could not load workspace.','error'))))}
async function refresh(){await Promise.all([loadMonth(),loadTasks(),loadTaskLists()])}
async function loadMonth(direction=0){const start=new Date(state.visibleMonth.getFullYear(),state.visibleMonth.getMonth(),1);const end=new Date(state.visibleMonth.getFullYear(),state.visibleMonth.getMonth()+1,0);try{const [events,tasks]=await Promise.all([api(`/events?from=${dateKey(start)}&to=${dateKey(end)}`),api(`/tasks?from=${dateKey(start)}&to=${dateKey(end)}&include_completed=false`)]);state.events=events.data.items||[];state.calendarTasks=tasks.data.items||[]}catch(error){state.events=[];state.calendarTasks=[];status(error.message||'Could not load calendar.','error')}renderCalendar();renderMiniCalendar();if(direction){const grid=state.calendarMode==='week'?$('week-grid'):$('calendar-grid');grid.animate([{opacity:.35,transform:`translateY(${direction>0?'16px':'-16px'})`},{opacity:1,transform:'translateY(0)'}],{duration:260,easing:'cubic-bezier(.2,0,0,1)'})}}
function renderCalendar(){const isWeek=state.calendarMode==='week';$('calendar-grid').hidden=isWeek;$('weekdays').hidden=isWeek;$('week-grid').hidden=!isWeek;setText('month-title',state.visibleMonth.toLocaleDateString(undefined,{month:'long',year:'numeric'}));if(isWeek){renderWeek();return}const grid=$('calendar-grid');grid.replaceChildren();const first=new Date(state.visibleMonth.getFullYear(),state.visibleMonth.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());const today=dateKey(new Date());for(let i=0;i<42;i++){const day=new Date(start);day.setDate(start.getDate()+i);const key=dateKey(day),summary=state.monthDays.get(key),button=document.createElement('button');button.type='button';button.className=`day${day.getMonth()!==state.visibleMonth.getMonth()?' outside':''}${key===state.selectedDate?' selected':''}${key===today?' today':''}`;button.setAttribute('aria-label',`${day.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}${summary?.task_count?`, ${summary.task_count} tasks`:''}`);const number=document.createElement('span');number.className='day-number';number.textContent=day.getDate();button.append(number);const items=[...state.events.filter(event=>event.starts_at?.slice(0,10)===key).map(item=>({item,type:'event'})),...state.calendarTasks.filter(task=>task.scheduled_date===key).map(item=>({item,type:'task'}))];items.slice(0,2).forEach(({item,type})=>{const pill=document.createElement('button');pill.type='button';pill.className=`event-pill${type==='task'?' task-pill':''}`;pill.textContent=item.title;pill.title=`Edit ${type}: ${item.title}`;pill.onclick=event=>{event.stopPropagation();type==='event'?openEvent(item):openTask(item)};button.append(pill)});if(items.length>2){const more=document.createElement('span');more.className='more';more.textContent=`+${items.length-2} more`;button.append(more)}button.onclick=()=>selectDate(key);grid.append(button)}}
function renderWeek(){const grid=$('week-grid');grid.replaceChildren();const selected=new Date(`${state.selectedDate}T00:00:00`),start=new Date(selected);start.setDate(selected.getDate()-selected.getDay());const blank=document.createElement('div');blank.className='week-day';grid.append(blank);const today=dateKey(new Date());const days=[];for(let col=0;col<7;col++){const day=new Date(start);day.setDate(start.getDate()+col);days.push(day);const head=document.createElement('div');head.className=`week-day${dateKey(day)===today?' today':''}`;head.innerHTML=`${day.toLocaleDateString(undefined,{weekday:'short'})}<strong>${day.getDate()}</strong>`;grid.append(head)}for(let hour=8;hour<=19;hour++){const label=document.createElement('div');label.className='week-time';label.textContent=`${String(hour).padStart(2,'0')}:00`;grid.append(label);days.forEach(day=>{const cell=document.createElement('button');cell.type='button';cell.className='week-cell';const key=dateKey(day);cell.onclick=()=>selectDate(key);[...state.events.filter(event=>event.starts_at?.slice(0,10)===key).filter(event=>event.all_day||Number(event.starts_at.slice(11,13))===hour),...state.calendarTasks.filter(task=>task.scheduled_date===key&&(task.all_day||Number((task.scheduled_time||'00:00').slice(0,2))===hour))].forEach(item=>{const eventTime=item.starts_at?.slice(11,16)||item.scheduled_time?.slice(0,5);const event=document.createElement('button');event.type='button';event.className='week-event';event.textContent=`${item.all_day?'All day':eventTime} ${item.title}`;event.onclick=click=>{click.stopPropagation();item.starts_at?openEvent(item):openTask(item)};cell.append(event)});grid.append(cell)})}}
function renderMiniCalendar(){const box=$('mini-calendar');box.replaceChildren();['S','M','T','W','T','F','S'].forEach(label=>{const item=document.createElement('span');item.className='mini-head';item.textContent=label;box.append(item)});const first=new Date(state.visibleMonth.getFullYear(),state.visibleMonth.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());for(let i=0;i<42;i++){const day=new Date(start);day.setDate(start.getDate()+i);const key=dateKey(day),item=document.createElement('button');item.type='button';item.className=`mini-day${day.getMonth()!==state.visibleMonth.getMonth()?' mini-outside':''}${key===state.selectedDate?' mini-selected':''}`;item.textContent=day.getDate();item.setAttribute('aria-label',day.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'}));item.onclick=()=>selectDate(key);box.append(item)}}
async function selectDate(date){state.selectedDate=date;state.visibleMonth=new Date(`${date}T00:00:00`);await loadMonth();openDatePrompt()}
function openDatePrompt(){setText('date-prompt-date',new Date(`${state.selectedDate}T00:00:00`).toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}));$('date-prompt-modal').reset();$('date-action-modal').hidden=false;$('date-prompt-input').focus()}
function reminderMinutes(id){const value=$(id).value;if(!value)return null;if(value==='custom'){const custom=Number($(id+'-custom').value);return custom>0?custom:null}return Number(value)}
async function saveQuick(event){event.preventDefault();const title=$('quick-title').value.trim(),description=$('quick-description').value.trim()||null,minutes=reminderMinutes('quick-reminder');try{let item;if(state.quickType==='event'){const response=await api('/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title,description,starts_at:$('quick-start').value,ends_at:$('quick-end').value||null,all_day:$('quick-all-day').checked,timezone:'Asia/Jakarta'})});item=response.data.event;await loadMonth()}else{const response=await api('/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title,description,task_list_id:$('quick-list-id').value||null,scheduled_date:state.selectedDate,scheduled_time:$('quick-start').value.slice(11,16)+':00',timezone:'Asia/Jakarta'})});item=response.data.task;await refresh()}if(minutes)await api('/reminders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({[state.quickType==='event'?'calendar_event_id':'task_id']:item.id,minutes_before:minutes,channel:$('quick-reminder-channel').value})});$('date-action-modal').hidden=true;status(`${state.quickType==='event'?'Event':'Task'} saved.`,'success')}catch(error){status(error.message||'Could not save item.','error')}}
function taskTime(task){return task.all_day?'All day':(task.scheduled_time||'No time').slice(0,5)}
async function loadAgenda(){const data=await api(`/agenda/day?date=${state.selectedDate}`);const items=data.data.items||[];setText('agenda-title',`Agenda · ${items.length}`);setText('agenda-date',new Date(`${state.selectedDate}T00:00:00`).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}));const box=$('agenda-items');box.replaceChildren();if(!items.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='Nothing scheduled for this date.';box.append(empty);return}items.forEach(task=>box.append(taskRow(task,'agenda-item')))}
async function loadTasks(){try{const data=await api('/tasks?include_completed=false');const completed=await api('/tasks?status=completed');state.allTasks=[...(data.data.items||[]),...(completed.data.items||[])]}catch(error){state.allTasks=[];status(error.message||'Could not load tasks.','error')}renderTaskBoard()}
async function loadTaskLists(){try{const data=await api('/task-lists');state.taskLists=data.data.items||[]}catch(error){state.taskLists=[];status(error.message||'Could not load lists.','error')}renderTaskBoard()}
function taskRow(task,className){const card=document.createElement('article');card.className=`${className}${task.status==='completed'?' completed':''}`;const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.className='check';checkbox.checked=task.status==='completed';checkbox.setAttribute('aria-label',`Complete ${task.title}`);checkbox.onchange=async()=>{try{if(task.status==='completed')return;await api(`/tasks/${task.id}/complete`,{method:'POST'});status('Task completed.','success');await refresh()}catch(error){checkbox.checked=false;status(error.message||'Could not complete task.','error')}};const body=document.createElement('button');body.type='button';body.className='agenda-main';const title=document.createElement('div');title.className='agenda-title';title.textContent=task.title;const meta=document.createElement('div');meta.className='agenda-meta';meta.textContent=task.scheduled_date?`${task.scheduled_date} · ${taskTime(task)}`:taskTime(task);body.append(title,meta);body.onclick=()=>openTask(task);card.append(checkbox,body);return card}
function renderTaskBoard(){const board=$('task-board');if(!board)return;board.replaceChildren();const visible=state.allTasks.filter(task=>state.taskFilter==='all'||(state.taskFilter==='today'?task.scheduled_date===dateKey(new Date()):task.scheduled_date>=dateKey(new Date())));const lists=state.taskLists.length?state.taskLists:[{id:null,name:'My Tasks'}];lists.forEach(list=>{const column=document.createElement('section');column.className='task-group';const head=document.createElement('div');head.className='task-group-head';const title=document.createElement('h2');title.textContent=list.name;const count=document.createElement('span');count.className='task-count';const items=visible.filter(task=>task.task_list_id===list.id||(list.name==='My Tasks'&&!task.task_list_id));count.textContent=items.length;head.append(title,count);const add=document.createElement('button');add.className='add-task-link';add.textContent='+ Add a task';add.onclick=()=>openTask(null,list.id);const body=document.createElement('div');body.className='task-list';if(!items.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='Belum ada task. Tambahkan pekerjaan pertama.';body.append(empty)}else items.forEach(task=>body.append(taskRow(task,'task-card')));column.append(head,add,body);board.append(column)})}
function fillTaskLists(selected=null){const select=$('task-list-id');select.replaceChildren();state.taskLists.forEach(list=>{const option=document.createElement('option');option.value=list.id;option.textContent=list.name;option.selected=list.id===selected;select.append(option)})}
function applyReminder(prefix,reminders=[]){const reminder=reminders.find(item=>item.status==='pending')||reminders[0];$(`${prefix}-reminder`).value=reminder?.minutes_before||'';$(`${prefix}-reminder-channel`).value=reminder?.channel||'whatsapp';$(`${prefix}-reminder-channel-field`).hidden=!reminder;$(`${prefix}-reminder-hint`).hidden=!reminder}
function openTask(task=null,listId=null){$('task-form').reset();$('task-id').value=task?.id||'';setText('form-title',task?'Edit task':'New task');$('task-title').value=task?.title||'';$('task-description').value=task?.description||'';$('task-date').value=task?.scheduled_date||state.selectedDate;$('task-time-visible').value=(task?.scheduled_time||'').slice(0,5);$('task-time').value=(task?.scheduled_time||'').slice(0,5);$('task-all-day').checked=!!task?.all_day;applyReminder('task',task?.reminders);fillTaskLists(task?.task_list_id||listId);$('delete-task').hidden=!task;$('task-modal').hidden=false}
function closeTask(){$('task-modal').hidden=true}
function openList(){$('list-form').reset();$('list-modal').hidden=false;$('list-name').focus()}
function closeList(){$('list-modal').hidden=true}
async function saveList(event){event.preventDefault();const name=$('list-name').value.trim();if(!name)return;try{await api('/task-lists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});closeList();await loadTaskLists()}catch(error){status(error.message||'Could not create list.','error')}}
function openEvent(event=null){$('event-form').reset();$('event-id').value=event?.id||'';setText('event-form-title',event?'Ubah jadwal':'Buat jadwal');$('event-title').value=event?.title||'';$('event-description').value=event?.description||'';const start=event?.starts_at?event.starts_at.slice(0,16):`${state.selectedDate}T09:00`;$('event-start').value=start;$('event-end').value=event?.ends_at?.slice(0,16)||'';$('event-all-day').checked=!!event?.all_day;applyReminder('event',event?.reminders);$('delete-event').hidden=!event;$('event-modal').hidden=false}
async function saveEvent(event){event.preventDefault();const id=$('event-id').value,payload={title:$('event-title').value.trim(),description:$('event-description').value.trim()||null,starts_at:$('event-start').value,ends_at:$('event-end').value||null,all_day:$('event-all-day').checked,timezone:'Asia/Jakarta'},minutes=reminderMinutes('event-reminder');try{const response=await api(id?`/events/${id}`:'/events',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(minutes)await api('/reminders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({calendar_event_id:response.data.event.id,minutes_before:minutes,channel:$('event-reminder-channel').value})});$('event-modal').hidden=true;status('Event saved.','success');await loadMonth()}catch(error){status(error.message||'Could not save event.','error')}}
async function deleteEvent(){const id=$('event-id').value;if(!id||!(await askConfirmation('Hapus event ini?','Event ini akan dihapus permanen.','Hapus event')))return;try{await api(`/events/${id}`,{method:'DELETE'});$('event-modal').hidden=true;await loadMonth()}catch(error){status(error.message||'Event tidak bisa dihapus.','error')}}
async function saveTask(event){event.preventDefault();const id=$('task-id').value,taskTime=$('task-time-visible').value,allDay=!taskTime,payload={title:$('task-title').value.trim(),description:$('task-description').value.trim()||null,task_list_id:$('task-list-id').value||null,scheduled_date:$('task-date').value||null,scheduled_time:taskTime?`${taskTime}:00`:null,timezone:'Asia/Jakarta',all_day:allDay},minutes=reminderMinutes('task-reminder');try{const response=await api(id?`/tasks/${id}`:'/tasks',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(minutes)await api('/reminders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:response.data.task.id,minutes_before:minutes,channel:$('task-reminder-channel').value})});closeTask();status('Task saved.','success');await refresh()}catch(error){status(error.message||'Could not save task.','error')}}
async function deleteTask(){const id=$('task-id').value;if(!id||!(await askConfirmation('Hapus task ini?','Task ini akan dihapus permanen.','Hapus task')))return;try{await api(`/tasks/${id}`,{method:'DELETE'});closeTask();status('Task deleted.','success');await refresh()}catch(error){status(error.message||'Task tidak bisa dihapus.','error')}}
function renderConfirmation(data){const box=$('confirmation');box.replaceChildren();const question=document.createElement('div');question.textContent=data.confirmation?.question||'Confirm this action?';const yes=document.createElement('button');yes.textContent='Confirm';yes.onclick=()=>confirmPrompt(true);const no=document.createElement('button');no.textContent='Cancel';no.onclick=()=>confirmPrompt(false);box.append(question,yes,no);box.hidden=false}
async function ask(text=$('prompt').value.trim(),selectedDate=null){if(!text)return;const button=$('ask');button.disabled=true;const box=$('chat-history');box.querySelector('.chat-empty')?.remove();chatMessage(text,'user');$('prompt').value='';const pending=chatMessage('Zaid sedang mengetik…','assistant');try{const data=await api('/prompts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,selected_date:selectedDate})});pending.textContent=data.data.human_response||data.message;if(data.data.requires_confirmation){state.pendingPrompt=data.data.prompt_request_id;renderConfirmation(data.data);return}await refresh()}catch(error){pending.textContent=error.message||'Could not process prompt.';pending.classList.add('error')}finally{button.disabled=false}}
async function confirmPrompt(confirmed){if(!state.pendingPrompt)return;try{const data=await api(`/prompts/${state.pendingPrompt}/confirm`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed})});state.pendingPrompt=null;$('confirmation').hidden=true;chatMessage(data.data.human_response||'Prompt updated.','assistant');if(confirmed)await refresh()}catch(error){chatMessage(error.message||'Could not confirm prompt.','assistant')}}
setInterval(()=>{if(document.visibilityState==='visible')refresh()},20000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh()});
function askConfirmation(title,copy,action){return new Promise(resolve=>{setText('confirm-title',title);setText('confirm-copy',copy);setText('confirm-ok',action);$('confirm-dialog').hidden=false;const finish=value=>{$('confirm-dialog').hidden=true;resolve(value)};$('confirm-cancel').onclick=()=>finish(false);$('confirm-ok').onclick=()=>finish(true)})}
$('clear-chat').onclick=async()=>{if(!await askConfirmation('Hapus riwayat chat?','Semua riwayat Ask Zaid akan dihapus permanen.','Hapus riwayat'))return;try{await api('/prompts',{method:'DELETE'});const box=$('chat-history');box.replaceChildren();box.append(renderChatEmpty('Riwayat sudah dihapus.'))}catch(error){status(error.message||'Riwayat tidak bisa dihapus.','error')}};
document.querySelectorAll('[data-prompt]').forEach(button=>button.onclick=()=>{$('prompt').value=button.dataset.prompt;$('prompt').focus()});
['task','event'].forEach(prefix=>{$(`${prefix}-reminder`).onchange=event=>{const active=!!event.target.value;$(`${prefix}-reminder-channel-field`).hidden=!active;$(`${prefix}-reminder-hint`).hidden=!active;$(`${prefix}-reminder-custom`).hidden=event.target.value!=='custom'}});
let calendarWheelLocked=false;$('calendar-panel').addEventListener('wheel',async event=>{if(state.calendarMode==='week'&&$('week-grid').scrollHeight>$('week-grid').clientHeight)return;if(Math.abs(event.deltaY)<24||calendarWheelLocked)return;event.preventDefault();calendarWheelLocked=true;const direction=event.deltaY>0?1:-1;if(state.calendarMode==='week'){const date=new Date(`${state.selectedDate}T00:00:00`);date.setDate(date.getDate()+direction*7);state.selectedDate=dateKey(date);state.visibleMonth=new Date(date.getFullYear(),date.getMonth(),1)}else state.visibleMonth.setMonth(state.visibleMonth.getMonth()+direction);await loadMonth(direction);setTimeout(()=>calendarWheelLocked=false,320)},{passive:false});
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>showView(button.dataset.view));document.querySelectorAll('[data-add-task]').forEach(button=>button.onclick=()=>openTask());$('new-task').onclick=()=>openEvent();$('date-prompt-modal').onsubmit=async event=>{event.preventDefault();const text=$('date-prompt-input').value.trim();if(!text)return;$('date-action-modal').hidden=true;await ask(text,state.selectedDate)};$('close-date-prompt').onclick=()=>{$('date-action-modal').hidden=true};$('quick-manual').onclick=()=>{$('date-action-modal').hidden=true;openEvent()};$('tasks-add').onclick=()=>openTask();$('new-list').onclick=openList;$('list-form').onsubmit=saveList;$('cancel-list').onclick=closeList;$('task-filter').onchange=event=>{state.taskFilter=event.target.value;renderTaskBoard()};$('calendar-mode').onchange=event=>{state.calendarMode=event.target.value;renderCalendar()};$('previous-month').onclick=async()=>{if(state.calendarMode==='week'){const date=new Date(`${state.selectedDate}T00:00:00`);date.setDate(date.getDate()-7);state.selectedDate=dateKey(date);state.visibleMonth=new Date(date.getFullYear(),date.getMonth(),1)}else state.visibleMonth.setMonth(state.visibleMonth.getMonth()-1);await loadMonth(-1)};$('next-month').onclick=async()=>{if(state.calendarMode==='week'){const date=new Date(`${state.selectedDate}T00:00:00`);date.setDate(date.getDate()+7);state.selectedDate=dateKey(date);state.visibleMonth=new Date(date.getFullYear(),date.getMonth(),1)}else state.visibleMonth.setMonth(state.visibleMonth.getMonth()+1);await loadMonth(1)};$('today').onclick=async()=>selectDate(dateKey(new Date()));$('today-nav').onclick=async()=>selectDate(dateKey(new Date()));$('tasks-nav').onclick=()=>showView('tasks');$('ask').onclick=ask;$('prompt').onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();ask()}};$('task-form').onsubmit=saveTask;$('cancel-task').onclick=closeTask;$('delete-task').onclick=deleteTask;$('event-form').onsubmit=saveEvent;$('cancel-event').onclick=$('close-event').onclick=()=>{$('event-modal').hidden=true};$('delete-event').onclick=deleteEvent;$('logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST'})}catch(error){}clearSession();location.replace('/app')};boot();
</script>
</body>
</html>
